CREATE TABLE IF NOT EXISTS gis_spatial_comparisons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), primary_dataset_id uuid NOT NULL REFERENCES gis_boundary_datasets(id) ON DELETE CASCADE, comparison_dataset_id uuid NOT NULL REFERENCES gis_boundary_datasets(id) ON DELETE CASCADE, run_reference text NOT NULL, status text NOT NULL DEFAULT 'Pending', primary_feature_count integer NOT NULL DEFAULT 0, comparison_feature_count integer NOT NULL DEFAULT 0, matched_count integer NOT NULL DEFAULT 0, unmatched_primary_count integer NOT NULL DEFAULT 0, unmatched_comparison_count integer NOT NULL DEFAULT 0, geometry_discrepancy_count integer NOT NULL DEFAULT 0, code_discrepancy_count integer NOT NULL DEFAULT 0, summary text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_spatial_comparison_features (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), comparison_id uuid NOT NULL REFERENCES gis_spatial_comparisons(id) ON DELETE CASCADE, primary_feature_id uuid, comparison_feature_id uuid, primary_area_code text, comparison_area_code text, primary_area_name text, comparison_area_name text, match_method text, overlap_ratio numeric, area_difference_ratio numeric, geometry_status text NOT NULL DEFAULT 'Pending', code_status text NOT NULL DEFAULT 'Pending', review_status text NOT NULL DEFAULT 'Pending', discrepancy_reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_spatial_comparisons_datasets ON gis_spatial_comparisons(primary_dataset_id,comparison_dataset_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_spatial_comparison_features_comparison ON gis_spatial_comparison_features(comparison_id,review_status,geometry_status,code_status);